entries[339056] = { ["name"] = "Andenken an Ursocs Wut", ["text"] = "Runenschnitzmacht\nIn Bärengestalt hat 'Hauen' eine Chance von 15%, dass 'Hauen' erneut ausgelöst wird.\n\n'Hauen' gewährt Euch einen Absorptionsschild in Höhe von 75% des verursachten Schadens.\nRunenschnitzen: Beine, Rücken\nQuelle: Beute von: Torghast, Turm der Verdammten. Kaltherzinterstitia, Ebene 3+\nBenötigt: Druide (Wächter)" }
