entries[339060] = { ["name"] = "Luffaversetzte Umarmung", ["text"] = "Runenschnitzmacht\nErhöht den Schaden von 'Hauen' um 20% und die Reichweite der Fähigkeit um 30%. Der Effekt ist bis zu 1-mal zusätzlich stapelbar.\nRunenschnitzen: Brust, Rücken\nQuelle: Dungeonbeute: Kryxis der Gefräßige\nBenötigt: Druide (Wächter)" }
entries[339061] = { ["name"] = "Ermächtigter Abschuss", ["text"] = "40 Meter Reichweite\nSofort\n'Schinderschuss' hat eine zusätzliche Chance von 5% , 'Mal des Schinders' auszulösen, und die Fähigkeit erhöht den Schaden Eures nächsten Einsatzes von 'Tödlicher Schuss' um 5.0% ." }
entries[339062] = { ["name"] = "Vermächtnis des Schläfers", ["text"] = "Runenschnitzmacht\n[ Inkarnation: Wächter von Ursoc : 'Inkarnation: Wächter von Ursoc' erhöht / In Bärengestalt erhöht 'Berserker'] Euren Schaden um 0%, Euren Lebensraub um 25% und macht Euch immun gegen Kontrollverlusteffekte.\n\nDie Abklingzeit der Fähigkeit ist um 30 Sek. verringert.\nRunenschnitzen: Taille, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Druide (Wächter)" }
entries[339063] = { ["name"] = "Wille der natürlichen Ordnung", ["text"] = "Runenschnitzmacht\n'Baumrinde' verringert den Schaden um zusätzlich 10%. Wenn Ihr Euch in Bärengestalt befindet, wenn der Effekt beginnt oder endet, erhaltet Ihr 'Eisenfell' und 'Rasende Regeneration'.\nRunenschnitzen: Kopf, Handgelenk, Hände\nQuelle: Schlachtzugbeute: Jäger Altimor\nBenötigt: Druide (Wächter)" }
