entries[339340] = { ["name"] = "Norgannons Klugheit", ["text"] = "Runenschnitzmacht\nDer Einsatz eines Zaubers gewährt 'Klugheit'. Bis zu 10-mal stapelbar. Wenn Ihr Euch bewegt, könnt Ihr pro Stapel von 'Klugheit' 0.5 Sek. lang Zauber aus der Bewegung wirken.\n(100ms Abklingzeit)\nRunenschnitzen: Beine, Füße, Rücken\nQuelle: Ihr benötigt einen respektvollen Ruf beim Hof der Ernter und müsst Runenschnitzen freigeschaltet haben, um diese Erinnerung kaufen zu können." }
entries[339341] = { ["name"] = "Ende der Nacht", ["text"] = "Sofort\nEure Fähigkeiten haben eine niedrige Chance, Euch 'Einbruch der Nacht' zu gewähren, was Euer Tempo für 12 Sek. um 456 erhöht. Wenn 'Einbruch der Nacht' abläuft, wird Euer Tempo für 8 Sek. um 112 verringert." }
